import{c as a,Q as i,j as t,m as n}from"./chunks/framework.DK3sgdKX.js";const u=JSON.parse('{"title":"PySTG Godot-style Editor Roadmap TODO","description":"","frontmatter":{},"headers":[],"relativePath":"EDITOR_ROADMAP_TODO.md","filePath":"EDITOR_ROADMAP_TODO.md","lastUpdated":1785576627000}'),r={name:"EDITOR_ROADMAP_TODO.md"};function s(o,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="pystg-godot-style-editor-roadmap-todo" tabindex="-1">PySTG Godot-style Editor Roadmap TODO <a class="header-anchor" href="#pystg-godot-style-editor-roadmap-todo" aria-label="Permalink to &quot;PySTG Godot-style Editor Roadmap TODO&quot;">​</a></h1><blockquote><p>Durable execution plan for agents and maintainers. Read this file before substantial editor, authoring-document, preview, UI/background authoring, or plugin work.</p></blockquote><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Build a low-threshold STG editor in which a new user can create and preview a bullet pattern without writing Python, while advanced users can progressively expand the same resource through curves, a typed behavior graph, scripts, custom editor extensions, UI/background authoring, and external-event adapters.</p><p>The product model is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Godot-style workbench</span></span>
<span class="line"><span>    + recipe-first danmaku authoring</span></span>
<span class="line"><span>    + timeline orchestration</span></span>
<span class="line"><span>    + formal runtime preview</span></span>
<span class="line"><span>    + script/plugin escape hatches</span></span></code></pre></div><h2 id="current-focus" tabindex="-1">Current focus <a class="header-anchor" href="#current-focus" aria-label="Permalink to &quot;Current focus&quot;">​</a></h2><p><strong>Milestone M2 — Controllable formal preview</strong></p><p>Phase 0 contracts are frozen. Keep later changes compatible with them or add explicit schema migrations and contract tests.</p><p>Next recommended task: <strong>E2.1 — Define PreviewController contract.</strong></p><h2 id="status-and-update-rules" tabindex="-1">Status and update rules <a class="header-anchor" href="#status-and-update-rules" aria-label="Permalink to &quot;Status and update rules&quot;">​</a></h2><ul><li><code>[ ]</code> means planned or incomplete.</li><li><code>[x]</code> means the task and its acceptance criteria are complete.</li><li>Put <code>BLOCKED:</code> after a task only when the blocking condition is concrete.</li><li>Do not mark an entire phase complete from unit tests alone when its gate also requires runtime or visual validation.</li><li>When completing a task, add a dated entry to the Completion log with commands, tests, artifacts, and known limitations.</li><li>If the design changes, update the decision here before implementing code that contradicts it.</li></ul><h2 id="non-negotiable-architecture-boundaries" tabindex="-1">Non-negotiable architecture boundaries <a class="header-anchor" href="#non-negotiable-architecture-boundaries" aria-label="Permalink to &quot;Non-negotiable architecture boundaries&quot;">​</a></h2><ol><li><strong>Bullets are not scene nodes.</strong> Scene documents contain semantic entities such as Stage, Boss, Spell, Emitter, and PatternInstance. High-density bullet state remains in the NumPy/Numba pool.</li><li><strong>Documents are the source of truth.</strong> Python generation is an optional compatibility/export path. Arbitrary Python is not reverse-parsed into a visual graph.</li><li><strong>Preview uses the formal runtime.</strong> Approximate Qt-only simulations may be used for diagnostics but must be labeled experimental and cannot establish visual/runtime parity.</li><li><strong>Progressive disclosure uses one resource.</strong> Recipe, curves, graph, and ScriptBehavior are increasingly powerful views/extensions of the same resource, not independent copies.</li><li><strong>Domain editors share infrastructure, not a universal graph.</strong> Danmaku, UI, background, scene, and script contexts share documents, resources, Inspector, Undo/Redo, timeline, preview, and plugin contracts while retaining domain-specific central views.</li><li><strong>Per-bullet behavior stays data-oriented.</strong> Compile common motion to pool fields, vectorized operations, or Numba-compatible kernels. Python callbacks are for sparse controllers/emitters, not every bullet every frame.</li><li><strong>External input enters through typed events.</strong> UDP, WebSocket, bots, and platform adapters do not directly mutate gameplay subsystems.</li><li><strong>No unrestricted <code>eval</code>.</strong> Expressions use a small typed/whitelisted AST.</li></ol><h2 id="audited-baseline-2026-08-01-snapshot" tabindex="-1">Audited baseline (2026-08-01 snapshot) <a class="header-anchor" href="#audited-baseline-2026-08-01-snapshot" aria-label="Permalink to &quot;Audited baseline (2026-08-01 snapshot)&quot;">​</a></h2><h3 id="reusable-foundation" tabindex="-1">Reusable foundation <a class="header-anchor" href="#reusable-foundation" aria-label="Permalink to &quot;Reusable foundation&quot;">​</a></h3><ul><li><code>src/editor/document.py</code>: UUIDs, schema version, validation, migration hook.</li><li><code>src/editor/storage.py</code>: project-constrained atomic persistence.</li><li><code>src/editor/commands.py</code> and <code>scene_commands.py</code>: basic Undo/Redo commands.</li><li><code>src/editor/app.py</code>: dockable Qt workbench, scene tree, Inspector, 2D view, resource drag/drop, Output and read-only Timeline.</li><li><code>src/editor/workbench.py</code>: central, bottom, and external plugin descriptors.</li><li><code>src/editor/asset_index.py</code> and <code>resource_browser.py</code>: project resource index, thumbnails, JSON sprite/animation subresources.</li><li><code>src/devtools/pattern_lab.py</code>: prototype PatternSpec and deterministic pattern parameter generation.</li><li><code>src/devtools/spell_preview.py</code>: pause, step, seek, reset, hot reload, error retention, and runtime statistics.</li><li><code>src/game/stage/context.py</code>: high-level content-to-engine API.</li><li><code>src/game/bullet/optimized_pool.py</code>: data-oriented high-density bullet runtime.</li><li><code>src/ui/components.py</code> and <code>ui_tree.py</code>: serializable UI tree prototype.</li><li><code>src/game/background_render/</code>: data-driven background loading and live reload.</li><li><code>src/game/emoji_danmaku/udp_receiver.py</code>: first external-input adapter candidate.</li></ul><h3 id="known-gaps-and-hazards" tabindex="-1">Known gaps and hazards <a class="header-anchor" href="#known-gaps-and-hazards" aria-label="Permalink to &quot;Known gaps and hazards&quot;">​</a></h3><ul><li>Scene documents do not compile or instantiate into the formal stage runtime.</li><li>Timeline is display-only and has no track/clip/keyframe mutation model.</li><li><code>PatternSpec</code> is a development model and code generation is one-way.</li><li>Pattern names are currently constrained as Python identifiers; display names and optional code symbols must be separated.</li><li>Editor scene defaults use a 768x896 pixel canvas, runtime logical dimensions are 384x448, and content APIs use normalized coordinates. A single coordinate contract is required before position authoring expands.</li><li><code>classify_file()</code> currently treats every <code>*.pystg.json</code> as a scene rather than inspecting its declared resource type.</li><li>The current CommandStack lacks transactions/coalescing for slider drags and multi-property edits.</li><li>ResourceService is primarily a texture compatibility service, not yet a typed authoring-resource loader/compiler registry.</li><li>Background code contains overlapping Camera/Fog/Layer models that must be unified before the editor freezes a public background schema.</li><li>There is no general runtime EventBus; the UDP emoji path is specialized.</li><li>The Qt workbench and resource-browser work was uncommitted in the audited snapshot. Always re-check current Git state rather than assuming that remains true.</li><li>Declared NumPy/Numba pins and the audited active environment differed. Resolve environment parity before performance gates.</li></ul><h3 id="audited-test-evidence" tabindex="-1">Audited test evidence <a class="header-anchor" href="#audited-test-evidence" aria-label="Permalink to &quot;Audited test evidence&quot;">​</a></h3><p>The following groups passed in the 2026-08-01 snapshot (55 tests total):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_editor_documents.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_editor_scene_commands.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_editor_workbench.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_editor_resource_browser.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_devtools_pattern_lab.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_devtools_spell_preview.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_devtools_hotreload.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_background_data_driven_parity.py tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_project_foundation.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QT_QPA_PLATFORM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;offscreen&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">test_editor_app_smoke.py</span></span></code></pre></div><p>This is historical evidence, not proof that the current checkout still passes.</p><h2 id="dependency-order" tabindex="-1">Dependency order <a class="header-anchor" href="#dependency-order" aria-label="Permalink to &quot;Dependency order&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 0: contracts</span></span>
<span class="line"><span>  -&gt; Phase 1: pattern IR/runtime</span></span>
<span class="line"><span>  -&gt; Phase 2: controllable formal preview</span></span>
<span class="line"><span>  -&gt; Phase 3: first no-code vertical slice</span></span>
<span class="line"><span>  -&gt; Phase 4: editable timeline/stage program</span></span>
<span class="line"><span>  -&gt; Phase 5: graph/expressions/scripts</span></span>
<span class="line"><span>  -&gt; Phase 6: UI and background contexts</span></span>
<span class="line"><span>  -&gt; Phase 7: events, plugin SDK, packaging hardening</span></span></code></pre></div><p>Phases may be researched in parallel, but public data/runtime contracts should not be implemented out of order.</p><hr><h2 id="phase-0-—-authoring-contracts" tabindex="-1">Phase 0 — Authoring contracts <a class="header-anchor" href="#phase-0-—-authoring-contracts" aria-label="Permalink to &quot;Phase 0 — Authoring contracts&quot;">​</a></h2><p>Goal: freeze the smallest durable document, coordinate, time, identity, and registry contracts before expanding UI.</p><h3 id="e0-1-common-typed-resource-envelope" tabindex="-1">E0.1 Common typed resource envelope <a class="header-anchor" href="#e0-1-common-typed-resource-envelope" aria-label="Permalink to &quot;E0.1 Common typed resource envelope&quot;">​</a></h3><ul><li>[x] Define a common resource header with <code>schema_version</code>, <code>type</code>, UUID <code>id</code>, Unicode <code>name</code>, and optional metadata.</li><li>[x] Define initial resource types: <code>pystg.scene</code>, <code>pystg.pattern</code>, <code>pystg.ui</code>, and <code>pystg.background</code>.</li><li>[x] Separate human display name, UUID identity, and optional Python <code>symbol_name</code>.</li><li>[x] Decide whether all typed resources retain <code>*.pystg.json</code> or receive domain-specific suffixes; document the decision.</li><li>[x] Add round-trip and duplicate-ID validation tests.</li><li>[x] Add explicit migration registration rather than a single hard-coded scene migration chain.</li></ul><p>Acceptance:</p><ul><li>Every initial resource type can load, validate, save, and reload without semantic changes.</li><li>Unicode display names never require a Python identifier.</li><li>Newer unsupported schema versions fail with actionable errors.</li></ul><h3 id="e0-2-resource-references-and-typed-registry" tabindex="-1">E0.2 Resource references and typed registry <a class="header-anchor" href="#e0-2-resource-references-and-typed-registry" aria-label="Permalink to &quot;E0.2 Resource references and typed registry&quot;">​</a></h3><ul><li>[x] Formalize <code>res://project/path#subresource</code> references.</li><li>[x] Replace the <code>*.pystg.json == scene</code> classification shortcut with declared type inspection.</li><li>[x] Introduce a ResourceTypeRegistry for loaders, validators, migrations, editor factories, compilers, and preview handlers.</li><li>[x] Keep project-boundary checks through <code>ProjectContext</code>.</li><li>[x] Add broken-reference and outside-project validation tests.</li></ul><p>Acceptance:</p><ul><li>The resource browser distinguishes scene, pattern, UI, and background documents and can report invalid resources without aborting the full scan.</li></ul><h3 id="e0-3-coordinate-and-time-contracts" tabindex="-1">E0.3 Coordinate and time contracts <a class="header-anchor" href="#e0-3-coordinate-and-time-contracts" aria-label="Permalink to &quot;E0.3 Coordinate and time contracts&quot;">​</a></h3><ul><li>[x] Define one logical gameplay coordinate space and document origin, axes, bounds, and conversion behavior.</li><li>[x] Add a CoordinateSpace service used by editor gizmos, document loading, runtime compilation, and preview.</li><li>[x] Decide document time storage (recommended: integer frames at a declared tick rate) and display conversion to seconds/beats.</li><li>[x] Remove new ad-hoc pixel/normalized conversion code.</li><li>[x] Add conversion round-trip and viewport-scaling tests.</li></ul><p>Acceptance:</p><ul><li>Dragging an emitter to a known editor position spawns at the same formal runtime position across window scales.</li></ul><h3 id="e0-4-property-and-node-registries" tabindex="-1">E0.4 Property and node registries <a class="header-anchor" href="#e0-4-property-and-node-registries" aria-label="Permalink to &quot;E0.4 Property and node registries&quot;">​</a></h3><ul><li>[x] Replace the single hard-coded NODE_TYPES map with a registry.</li><li>[x] Extend PropertySpec with enum, resource reference, unit, group, range, curve/binding capability, conditional visibility, and editor hints.</li><li>[x] Define initial semantic scene types: Stage, Boss, Spell, Emitter, and PatternInstance.</li><li>[x] Define valid parent/child constraints and registry-level validation.</li><li>[x] Add registry collision and unknown-type tests.</li></ul><p>Acceptance:</p><ul><li>A registered node type can supply its schema, Inspector fields, validation, viewport behavior, and runtime compiler without modifying a central switch.</li></ul><h3 id="phase-0-gate" tabindex="-1">Phase 0 gate <a class="header-anchor" href="#phase-0-gate" aria-label="Permalink to &quot;Phase 0 gate&quot;">​</a></h3><ul><li>[x] All E0 tasks complete.</li><li>[x] Versioned schema and migrations documented.</li><li>[x] Coordinate parity test passes.</li><li>[x] Relevant tests pass in the pinned development environment.</li><li>[x] Architecture review confirms later phases can compile through registries without adding type-specific conditionals to the editor shell.</li></ul><hr><h2 id="phase-1-—-pattern-ir-and-formal-runtime-execution" tabindex="-1">Phase 1 — Pattern IR and formal runtime execution <a class="header-anchor" href="#phase-1-—-pattern-ir-and-formal-runtime-execution" aria-label="Permalink to &quot;Phase 1 — Pattern IR and formal runtime execution&quot;">​</a></h2><p>Goal: make data-authored patterns directly runnable without generating Python.</p><h3 id="e1-1-patterndocument" tabindex="-1">E1.1 PatternDocument <a class="header-anchor" href="#e1-1-patterndocument" aria-label="Permalink to &quot;E1.1 PatternDocument&quot;">​</a></h3><ul><li>[x] Define recipe-level sections: Bullet, Shape, Aim, Schedule, Motion, and Modifiers.</li><li>[x] Support initial shapes: ring, arc, line, spiral, and random distribution.</li><li>[x] Support initial scheduling: delay, interval, burst count, loop.</li><li>[x] Support fixed direction and aim-at-player.</li><li>[x] Support stable random seed configuration.</li><li>[x] Provide migration/import from the prototype PatternSpec.</li></ul><h3 id="e1-2-pattern-compiler" tabindex="-1">E1.2 Pattern compiler <a class="header-anchor" href="#e1-2-pattern-compiler" aria-label="Permalink to &quot;E1.2 Pattern compiler&quot;">​</a></h3><ul><li>[x] Implement <code>PatternDocument -&gt; immutable PatternProgram</code> compilation.</li><li>[x] Resolve and validate resource references during compilation.</li><li>[x] Precompute static angles, speeds, and resource indices.</li><li>[x] Produce structured diagnostics containing resource ID and property path.</li><li>[x] Cache compiled programs using content/version identity.</li></ul><h3 id="e1-3-pattern-runner" tabindex="-1">E1.3 Pattern runner <a class="header-anchor" href="#e1-3-pattern-runner" aria-label="Permalink to &quot;E1.3 Pattern runner&quot;">​</a></h3><ul><li>[x] Implement a fixed-tick PatternRunner that executes PatternProgram through StageContext.</li><li>[x] Define start, pause, reset, stop, and deterministic replay semantics.</li><li>[x] Track ownership/tags so a pattern instance can clear or transform only its own bullets.</li><li>[x] Add batch spawn APIs to StageContext and OptimizedBulletPool.</li><li>[x] Keep common bullet motion in NumPy/Numba-compatible data paths.</li></ul><h3 id="e1-4-runtime-parity-tests" tabindex="-1">E1.4 Runtime parity tests <a class="header-anchor" href="#e1-4-runtime-parity-tests" aria-label="Permalink to &quot;E1.4 Runtime parity tests&quot;">​</a></h3><ul><li>[x] Compare compiled output against known PatternSpec parameter fixtures.</li><li>[x] Verify identical seeds produce identical spawn traces.</li><li>[x] Verify preview and gameplay runners produce identical traces.</li><li>[x] Add load/compile/run failure tests with actionable diagnostics.</li><li>[x] Add representative dense-burst performance measurements after dependency versions are aligned.</li></ul><h3 id="phase-1-gate" tabindex="-1">Phase 1 gate <a class="header-anchor" href="#phase-1-gate" aria-label="Permalink to &quot;Phase 1 gate&quot;">​</a></h3><ul><li>[x] One PatternDocument runs in the formal game runtime without Python codegen.</li><li>[x] Ring, arc, spiral, aim, interval, multi-burst, and random-seed parity pass.</li><li>[x] Dense patterns do not require scene nodes or per-bullet Python callbacks.</li><li>[x] Runtime and structural tests pass; performance evidence is recorded.</li></ul><hr><h2 id="phase-2-—-controllable-formal-preview" tabindex="-1">Phase 2 — Controllable formal preview <a class="header-anchor" href="#phase-2-—-controllable-formal-preview" aria-label="Permalink to &quot;Phase 2 — Controllable formal preview&quot;">​</a></h2><p>Goal: turn the existing preview runtime into an editor-controlled service.</p><h3 id="e2-1-previewcontroller-contract" tabindex="-1">E2.1 PreviewController contract <a class="header-anchor" href="#e2-1-previewcontroller-contract" aria-label="Permalink to &quot;E2.1 PreviewController contract&quot;">​</a></h3><ul><li>[ ] Define load, play, pause, step, seek, reset, stop, set-property, set-player-position, set-seed, and get-stats commands.</li><li>[ ] Define structured status, compile error, runtime error, and statistics events.</li><li>[ ] Preserve the last valid program when a hot reload fails.</li><li>[ ] Make lifecycle/cleanup idempotent.</li></ul><h3 id="e2-2-process-transport" tabindex="-1">E2.2 Process transport <a class="header-anchor" href="#e2-2-process-transport" aria-label="Permalink to &quot;E2.2 Process transport&quot;">​</a></h3><ul><li>[ ] Implement QProcess lifecycle management.</li><li>[ ] Use newline-delimited JSON over stdin/stdout for the first transport.</li><li>[ ] Add protocol version negotiation and request IDs.</li><li>[ ] Ensure child crashes and malformed output cannot freeze the editor.</li><li>[ ] Add protocol and subprocess smoke tests.</li></ul><h3 id="e2-3-preview-surface" tabindex="-1">E2.3 Preview surface <a class="header-anchor" href="#e2-3-preview-surface" aria-label="Permalink to &quot;E2.3 Preview surface&quot;">​</a></h3><ul><li>[ ] First integrate controllable external-window formal preview.</li><li>[ ] Show frame, bullet count, update/render timing, seed, pause state, and last compile/runtime error in the editor.</li><li>[ ] Add optional diagnostic gizmos without changing formal bullet behavior.</li><li>[ ] Research QOpenGLWidget + ModernGL attachment only after the controller contract is stable.</li><li>[ ] Treat full <code>main.py</code> embedding as deferred; start with spell/pattern preview.</li></ul><h3 id="phase-2-gate" tabindex="-1">Phase 2 gate <a class="header-anchor" href="#phase-2-gate" aria-label="Permalink to &quot;Phase 2 gate&quot;">​</a></h3><ul><li>[ ] Inspector-driven changes reload a PatternDocument without Python codegen.</li><li>[ ] Pause, step, seek, reset, seed, and player-position control work.</li><li>[ ] Formal preview survives an invalid edit and recovers after correction.</li><li>[ ] Runtime parity and visual preview are both checked and recorded separately.</li></ul><hr><h2 id="phase-3-—-first-no-code-vertical-slice" tabindex="-1">Phase 3 — First no-code vertical slice <a class="header-anchor" href="#phase-3-—-first-no-code-vertical-slice" aria-label="Permalink to &quot;Phase 3 — First no-code vertical slice&quot;">​</a></h2><p>Goal: let a new user create, save, reopen, and formally preview a complete simple spell without writing Python.</p><h3 id="e3-1-multi-document-editing" tabindex="-1">E3.1 Multi-document editing <a class="header-anchor" href="#e3-1-multi-document-editing" aria-label="Permalink to &quot;E3.1 Multi-document editing&quot;">​</a></h3><ul><li>[ ] Replace the single SceneEditorSession assumption with DocumentManager.</li><li>[ ] Give each open document its own savepoint and CommandStack.</li><li>[ ] Add close/save/revert behavior for multiple documents.</li><li>[ ] Preserve resource selections and editor context per document.</li></ul><h3 id="e3-2-undo-transactions" tabindex="-1">E3.2 Undo transactions <a class="header-anchor" href="#e3-2-undo-transactions" aria-label="Permalink to &quot;E3.2 Undo transactions&quot;">​</a></h3><ul><li>[ ] Add command transactions for multi-property operations.</li><li>[ ] Coalesce continuous slider/spinbox/gizmo drags into one undo step.</li><li>[ ] Add timeline and resource-assignment command types.</li><li>[ ] Verify Undo/Redo round-trips valid documents.</li></ul><h3 id="e3-3-contextual-pattern-workspace" tabindex="-1">E3.3 Contextual Pattern workspace <a class="header-anchor" href="#e3-3-contextual-pattern-workspace" aria-label="Permalink to &quot;E3.3 Contextual Pattern workspace&quot;">​</a></h3><ul><li>[ ] Add Pattern as a first-class central editor context.</li><li>[ ] Provide recipe Inspector controls with units and advanced sections.</li><li>[ ] Add Bullet resource picking and drag/drop.</li><li>[ ] Add emitter gizmo, player target gizmo, and optional trajectory guides.</li><li>[ ] Connect property changes to PreviewController.</li><li>[ ] Provide concise empty states and starter templates.</li></ul><h3 id="e3-4-scene-integration" tabindex="-1">E3.4 Scene integration <a class="header-anchor" href="#e3-4-scene-integration" aria-label="Permalink to &quot;E3.4 Scene integration&quot;">​</a></h3><ul><li>[ ] Add Stage -&gt; Boss -&gt; Spell -&gt; Emitter/PatternInstance creation flow.</li><li>[ ] Support Pattern resource instancing rather than copying definitions.</li><li>[ ] Compile the selected simple Spell into a runnable preview program.</li><li>[ ] Provide structured Output messages that link to the failing node/property.</li></ul><h3 id="phase-3-gate-—-first-product-milestone" tabindex="-1">Phase 3 gate — first product milestone <a class="header-anchor" href="#phase-3-gate-—-first-product-milestone" aria-label="Permalink to &quot;Phase 3 gate — first product milestone&quot;">​</a></h3><ul><li>[ ] A clean user flow can create a ring pattern, adjust count/speed/interval, aim at the player, assign a bullet resource, save, reopen, and formally preview it without touching Python.</li><li>[ ] Undo/Redo covers creation, resource assignment, gizmo movement, and property editing.</li><li>[ ] Desktop interaction and representative narrow-layout behavior are checked.</li><li>[ ] Structural, runtime, and visual acceptance are recorded separately.</li></ul><hr><h2 id="phase-4-—-editable-timeline-and-stageprogram" tabindex="-1">Phase 4 — Editable timeline and StageProgram <a class="header-anchor" href="#phase-4-—-editable-timeline-and-stageprogram" aria-label="Permalink to &quot;Phase 4 — Editable timeline and StageProgram&quot;">​</a></h2><p>Goal: author a 30-60 second spell or stage segment through tracks and clips.</p><h3 id="e4-1-timeline-document-model" tabindex="-1">E4.1 Timeline document model <a class="header-anchor" href="#e4-1-timeline-document-model" aria-label="Permalink to &quot;E4.1 Timeline document model&quot;">​</a></h3><ul><li>[ ] Replace the flat display-only event list with Track, Clip, and Keyframe models.</li><li>[ ] Give every track/clip/keyframe a stable UUID.</li><li>[ ] Define start frame, duration, target UUID, channel, ordering, looping, interpolation, and payload contracts.</li><li>[ ] Define initial clips: Pattern, Movement, Audio, Event, and Property.</li><li>[ ] Add migration from legacy flat TimelineEvent entries.</li></ul><h3 id="e4-2-timeline-editor" tabindex="-1">E4.2 Timeline editor <a class="header-anchor" href="#e4-2-timeline-editor" aria-label="Permalink to &quot;E4.2 Timeline editor&quot;">​</a></h3><ul><li>[ ] Build a QGraphicsScene-based ruler, tracks, clips, playhead, selection, and snapping interaction.</li><li>[ ] Add clip creation, movement, resize, duplication, deletion, and Undo/Redo.</li><li>[ ] Connect playhead scrubbing to formal preview seek.</li><li>[ ] Support zoom without changing stored frame values.</li><li>[ ] Add keyboard and focus behavior tests.</li></ul><h3 id="e4-3-stageprogram-compiler-runtime" tabindex="-1">E4.3 StageProgram compiler/runtime <a class="header-anchor" href="#e4-3-stageprogram-compiler-runtime" aria-label="Permalink to &quot;E4.3 StageProgram compiler/runtime&quot;">​</a></h3><ul><li>[ ] Compile Scene + Timeline + referenced resources into StageProgram.</li><li>[ ] Schedule pattern, movement, audio, property, and typed-event clips.</li><li>[ ] Define conflict resolution when multiple clips target the same property.</li><li>[ ] Retain ScriptEvent as an explicit escape hatch.</li><li>[ ] Add deterministic stage trace tests.</li></ul><h3 id="phase-4-gate" tabindex="-1">Phase 4 gate <a class="header-anchor" href="#phase-4-gate" aria-label="Permalink to &quot;Phase 4 gate&quot;">​</a></h3><ul><li>[ ] A 30-60 second spell can be authored and previewed using scene, pattern, movement, audio, and property tracks.</li><li>[ ] Timeline edits support Undo/Redo and survive save/reopen.</li><li>[ ] Scrubbing and normal playback agree at deterministic checkpoints.</li></ul><hr><h2 id="phase-5-—-behavior-graph-curves-expressions-scripts" tabindex="-1">Phase 5 — Behavior graph, curves, expressions, scripts <a class="header-anchor" href="#phase-5-—-behavior-graph-curves-expressions-scripts" aria-label="Permalink to &quot;Phase 5 — Behavior graph, curves, expressions, scripts&quot;">​</a></h2><p>Goal: raise the authoring ceiling without replacing or forking recipe resources.</p><h3 id="e5-1-curves-and-bindings" tabindex="-1">E5.1 Curves and bindings <a class="header-anchor" href="#e5-1-curves-and-bindings" aria-label="Permalink to &quot;E5.1 Curves and bindings&quot;">​</a></h3><ul><li>[ ] Define reusable Curve resources/keyframes and interpolation modes.</li><li>[ ] Allow eligible properties to bind constants, curves, variables, or restricted expressions.</li><li>[ ] Provide a small whitelisted expression AST; never unrestricted eval.</li><li>[ ] Initially expose variables such as frame, time, burst index, player/boss position, and deterministic random values.</li><li>[ ] Compile expressions with property-path diagnostics.</li></ul><h3 id="e5-2-typed-behavior-graph" tabindex="-1">E5.2 Typed behavior graph <a class="header-anchor" href="#e5-2-typed-behavior-graph" aria-label="Permalink to &quot;E5.2 Typed behavior graph&quot;">​</a></h3><ul><li>[ ] Define stable node categories: Source, Shape, Aim, Schedule, Motion, Modifier, Condition, Event, and ScriptBehavior.</li><li>[ ] Define typed ports, connection rules, cycle policy, and graph validation.</li><li>[ ] Compile graphs into the same PatternProgram used by recipe mode.</li><li>[ ] Provide recipe-to-graph expansion without producing a detached copy.</li><li>[ ] Build the graph UI only after compiler tests establish the contract.</li></ul><h3 id="e5-3-scriptbehavior" tabindex="-1">E5.3 ScriptBehavior <a class="header-anchor" href="#e5-3-scriptbehavior" aria-label="Permalink to &quot;E5.3 ScriptBehavior&quot;">​</a></h3><ul><li>[ ] Define explicit script lifecycle and typed context APIs.</li><li>[ ] Support sparse controller/emitter logic and event hooks.</li><li>[ ] Prevent accidental per-bullet Python update registration by default.</li><li>[ ] Surface import/runtime errors through the same diagnostic protocol.</li><li>[ ] Keep Python export optional and one-way.</li></ul><h3 id="phase-5-gate" tabindex="-1">Phase 5 gate <a class="header-anchor" href="#phase-5-gate" aria-label="Permalink to &quot;Phase 5 gate&quot;">​</a></h3><ul><li>[ ] The same saved resource progresses from recipe to curves/expressions to graph and optional script without format forking.</li><li>[ ] Common graph motion remains on data-oriented runtime paths.</li><li>[ ] Invalid graphs/expressions cannot crash the editor or corrupt the resource.</li></ul><hr><h2 id="phase-6-—-ui-and-background-authoring-contexts" tabindex="-1">Phase 6 — UI and background authoring contexts <a class="header-anchor" href="#phase-6-—-ui-and-background-authoring-contexts" aria-label="Permalink to &quot;Phase 6 — UI and background authoring contexts&quot;">​</a></h2><p>Goal: reuse the workbench and runtime bridge for specialized UI and background editing without forcing them into the danmaku graph.</p><h3 id="e6-1-ui-document-runtime-alignment" tabindex="-1">E6.1 UI document/runtime alignment <a class="header-anchor" href="#e6-1-ui-document-runtime-alignment" aria-label="Permalink to &quot;E6.1 UI document/runtime alignment&quot;">​</a></h3><ul><li>[ ] Add UUIDs, schema version, typed resource header, and migrations to UI documents.</li><li>[ ] Add anchors, margins, horizontal/vertical/grid containers, styles/theme references, data bindings, and animatable properties.</li><li>[ ] Ensure every supported UI node has formal renderer behavior.</li><li>[ ] Build UI-specific scene tree, canvas gizmos, Inspector, and resource drag.</li><li>[ ] Add viewport-size/responsive preview presets.</li></ul><h3 id="e6-2-background-schema-unification" tabindex="-1">E6.2 Background schema unification <a class="header-anchor" href="#e6-2-background-schema-unification" aria-label="Permalink to &quot;E6.2 Background schema unification&quot;">​</a></h3><ul><li>[ ] Inventory and reconcile duplicate Camera, Fog, Layer, texture, scroll, and blend fields.</li><li>[ ] Define one BackgroundDocument consumed by editor and runtime.</li><li>[ ] Add migration/import for existing background JSON files.</li><li>[ ] Build layer list, camera/fog Inspector, transform gizmos, and timeline bindings.</li><li>[ ] Reuse formal background reload/render path for preview.</li></ul><h3 id="phase-6-gate" tabindex="-1">Phase 6 gate <a class="header-anchor" href="#phase-6-gate" aria-label="Permalink to &quot;Phase 6 gate&quot;">​</a></h3><ul><li>[ ] UI and background resources share document, resource, Inspector, Undo/Redo, timeline, and preview infrastructure.</li><li>[ ] Existing shipped UI/background resources migrate or import without unreviewed visual regressions.</li><li>[ ] Desktop and responsive UI previews receive visual QA.</li></ul><hr><h2 id="phase-7-—-events-plugin-sdk-and-hardening" tabindex="-1">Phase 7 — Events, plugin SDK, and hardening <a class="header-anchor" href="#phase-7-—-events-plugin-sdk-and-hardening" aria-label="Permalink to &quot;Phase 7 — Events, plugin SDK, and hardening&quot;">​</a></h2><p>Goal: support external integrations and long-term extensibility after the core contracts have stabilized.</p><h3 id="e7-1-runtime-eventbus" tabindex="-1">E7.1 Runtime EventBus <a class="header-anchor" href="#e7-1-runtime-eventbus" aria-label="Permalink to &quot;E7.1 Runtime EventBus&quot;">​</a></h3><ul><li>[ ] Define typed Event with type, source, frame/timestamp, and payload.</li><li>[ ] Provide a main-thread queue and deterministic dispatch order.</li><li>[ ] Add scene/timeline/script subscription and emission APIs.</li><li>[ ] Refactor the emoji UDP path into the first EventAdapter.</li><li>[ ] Add queue limits, malformed-event handling, and shutdown behavior.</li></ul><h3 id="e7-2-external-adapter-protocol" tabindex="-1">E7.2 External adapter protocol <a class="header-anchor" href="#e7-2-external-adapter-protocol" aria-label="Permalink to &quot;E7.2 External adapter protocol&quot;">​</a></h3><ul><li>[ ] Define adapter lifecycle, configuration, health/status, and event schemas.</li><li>[ ] Prefer out-of-process adapters for network-facing or untrusted code.</li><li>[ ] Add local IPC transport without requiring a general web server.</li><li>[ ] Add example UDP and WebSocket/bot adapters only after the protocol is stable.</li><li>[ ] Document security boundaries and non-goals.</li></ul><h3 id="e7-3-plugin-sdk" tabindex="-1">E7.3 Plugin SDK <a class="header-anchor" href="#e7-3-plugin-sdk" aria-label="Permalink to &quot;E7.3 Plugin SDK&quot;">​</a></h3><ul><li>[ ] Define plugin manifest/API version.</li><li>[ ] Register resource types, node types, Inspector editors, central/bottom views, commands, importers, compilers, preview handlers, and adapters.</li><li>[ ] Define plugin activation/deactivation and failure isolation.</li><li>[ ] Decide project-local plugin discovery and Python package entry points.</li><li>[ ] Add compatibility and duplicate-registration tests.</li></ul><h3 id="e7-4-product-hardening" tabindex="-1">E7.4 Product hardening <a class="header-anchor" href="#e7-4-product-hardening" aria-label="Permalink to &quot;E7.4 Product hardening&quot;">​</a></h3><ul><li>[ ] Decide/migrate Qt binding before public distribution; prefer PySide6 for an MIT/LGPL-compatible public editor unless a PyQt commercial license exists.</li><li>[ ] Align declared and active dependency versions.</li><li>[ ] Add autosave/recovery without bypassing atomic persistence.</li><li>[ ] Persist safe workspace layout and open-document state.</li><li>[ ] Add crash diagnostics and corrupt-document recovery UX.</li><li>[ ] Add migration fixtures from every released schema version.</li><li>[ ] Establish full structural, runtime, performance, and visual release gates.</li></ul><h3 id="phase-7-gate" tabindex="-1">Phase 7 gate <a class="header-anchor" href="#phase-7-gate" aria-label="Permalink to &quot;Phase 7 gate&quot;">​</a></h3><ul><li>[ ] External events can drive authored content through typed contracts.</li><li>[ ] A sample plugin can add a resource/node/editor/runtime contribution without patching core registries.</li><li>[ ] Packaging, licensing, recovery, migrations, and release QA are documented and verified.</li></ul><hr><h2 id="explicitly-deferred-until-their-prerequisites-pass" tabindex="-1">Explicitly deferred until their prerequisites pass <a class="header-anchor" href="#explicitly-deferred-until-their-prerequisites-pass" aria-label="Permalink to &quot;Explicitly deferred until their prerequisites pass&quot;">​</a></h2><ul><li>[ ] Full arbitrary Python round-trip parsing — intentionally not planned.</li><li>[ ] Expanding bullets into Scene Tree objects — prohibited by architecture.</li><li>[ ] A universal graph for UI, background, stage, and danmaku — not planned.</li><li>[ ] Embedding the entire <code>main.py</code> game loop in Qt before PreviewController is stable.</li><li>[ ] Public plugin marketplace before the plugin API/versioning contract is stable.</li><li>[ ] Redis, web services, or remote collaboration infrastructure without a demonstrated requirement.</li><li>[ ] Binary document packing before JSON size/load measurements justify it.</li></ul><h2 id="expected-module-direction" tabindex="-1">Expected module direction <a class="header-anchor" href="#expected-module-direction" aria-label="Permalink to &quot;Expected module direction&quot;">​</a></h2><p>Names are provisional; preserve responsibilities even if paths change.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/authoring/</span></span>
<span class="line"><span>  resources.py          common envelope and resource references</span></span>
<span class="line"><span>  registry.py           resource/node/compiler/preview registries</span></span>
<span class="line"><span>  migrations.py         version migration routing</span></span>
<span class="line"><span>  coordinates.py        formal editor/runtime coordinate conversion</span></span>
<span class="line"><span></span></span>
<span class="line"><span>src/pattern/</span></span>
<span class="line"><span>  document.py           PatternDocument</span></span>
<span class="line"><span>  ir.py                 immutable PatternProgram</span></span>
<span class="line"><span>  compiler.py           document/graph -&gt; program</span></span>
<span class="line"><span>  runtime.py            PatternRunner</span></span>
<span class="line"><span>  expressions.py        restricted expression AST</span></span>
<span class="line"><span></span></span>
<span class="line"><span>src/editor/</span></span>
<span class="line"><span>  document_manager.py   multi-document/savepoint ownership</span></span>
<span class="line"><span>  preview_controller.py editor-side preview API</span></span>
<span class="line"><span>  preview_protocol.py   versioned process messages</span></span>
<span class="line"><span>  contexts/             scene, pattern, timeline, UI, background views</span></span>
<span class="line"><span></span></span>
<span class="line"><span>src/game/</span></span>
<span class="line"><span>  events.py             runtime EventBus</span></span>
<span class="line"><span>  stage/program.py      StageProgram runtime</span></span></code></pre></div><p>Avoid creating these modules merely to satisfy the directory sketch. Add them when their roadmap task begins and a tested responsibility exists.</p><h2 id="merge-and-acceptance-discipline" tabindex="-1">Merge and acceptance discipline <a class="header-anchor" href="#merge-and-acceptance-discipline" aria-label="Permalink to &quot;Merge and acceptance discipline&quot;">​</a></h2><p>For every milestone, report these separately:</p><ol><li><strong>Planned:</strong> design/task is documented but not implemented.</li><li><strong>Structurally valid:</strong> schema, unit, migration, and contract tests pass.</li><li><strong>Runtime valid:</strong> formal runtime/preview behavior matches expected traces.</li><li><strong>Performance checked:</strong> representative workload measured in the pinned target environment.</li><li><strong>Visually accepted:</strong> editor interaction and rendered output were inspected locally; structural tests alone do not imply this state.</li></ol><p>Minimum repository checks remain defined in <code>docs/EDITOR_ARCHITECTURE.md</code>.</p><h2 id="completion-log" tabindex="-1">Completion log <a class="header-anchor" href="#completion-log" aria-label="Permalink to &quot;Completion log&quot;">​</a></h2><p>Append entries; do not rewrite old evidence. Keep each entry concise.</p><h3 id="_2026-08-01-—-roadmap-captured" tabindex="-1">2026-08-01 — Roadmap captured <a class="header-anchor" href="#_2026-08-01-—-roadmap-captured" aria-label="Permalink to &quot;2026-08-01 — Roadmap captured&quot;">​</a></h3><ul><li>Added the durable phased roadmap and root agent entry point.</li><li>Recorded the audited editor/runtime baseline and known architectural gaps.</li><li>No implementation phase was marked complete by this documentation-only step.</li></ul><h3 id="_2026-08-01-—-m0-authoring-contracts-complete" tabindex="-1">2026-08-01 — M0 authoring contracts complete <a class="header-anchor" href="#_2026-08-01-—-m0-authoring-contracts-complete" aria-label="Permalink to &quot;2026-08-01 — M0 authoring contracts complete&quot;">​</a></h3><ul><li>Froze the <code>*.pystg.json</code> typed envelope, four initial resource types, UUID identity, Unicode display names, optional <code>symbol_name</code>, and explicit v0→v1 scene migration.</li><li>Added canonical <code>res://path#fragment</code> references, project-boundary validation, atomic typed-resource storage, declared-type asset classification, and a contribution registry for loaders, validators, editors, compilers, previews, and migrations.</li><li>Standardized authoring coordinates at 384×448 top-left/Y-down, runtime coordinates at center-origin <code>[-1, 1]</code>/Y-up, and time at non-negative integer frames with a declared tick rate.</li><li>Replaced the hard-coded node map with an extensible registry and registered Stage, Boss, Spell, Emitter, and PatternInstance schemas, constraints, Inspector metadata, viewport behavior, and compiler contribution slots.</li><li>Structural evidence: 36 M0/editor tests passed in an isolated Python 3.12 environment with pinned NumPy 2.2.4, Numba 0.63.1, pytest 8.4.1, and PyQt5 5.15.10; the <code>touhou_guess</code> target environment passed the full 103-test suite.</li><li>Repository evidence: <code>python -m compileall -q main.py src game_content tools</code> passed; asset validation checked 71 JSON files, 745 sprites, and 142 images with 0 errors and 0 warnings.</li><li>Visual evidence: a native Qt 1440×900 render was inspected locally; the Scene tree, 384×448 canvas, Inspector, and Output/Timeline/Assets tabs were readable with no visible layout regression. Mouse automation was not accepted for the custom <code>pythonw.exe</code>, so interaction acceptance remains test-backed.</li><li>Known reproducibility limitation: a clean full <code>requirements-dev.txt</code> install could not be completed from the configured Tsinghua mirror because <code>imgui==2.0.0</code> had no binary wheel and its source build stalled. The existing target conda environment was used for the full regression.</li><li>Acceptance classification: M0 is structurally valid and visually inspected. Pattern runtime parity and performance remain Phase 1+ work.</li></ul><h3 id="_2026-08-01-—-m1-pattern-ir-and-formal-runtime-complete" tabindex="-1">2026-08-01 — M1 pattern IR and formal runtime complete <a class="header-anchor" href="#_2026-08-01-—-m1-pattern-ir-and-formal-runtime-complete" aria-label="Permalink to &quot;2026-08-01 — M1 pattern IR and formal runtime complete&quot;">​</a></h3><ul><li>Added strict <code>PatternDocument</code> v1 and Draft 2020-12 schema with Bullet, Shape, Aim, Schedule, Motion, Modifiers, stable seed, Unicode display identity, and direct import from the development <code>PatternSpec</code> without Python codegen.</li><li>Added content/dependency-keyed compilation into immutable <code>PatternProgram</code> templates, alias/direct-fragment resolution, optional sprite-index precomputation, bounded compile size, and structured resource/property diagnostics.</li><li>Added deterministic fixed-tick <code>PatternRunner</code> lifecycle and owner-tag isolation, plus vectorized <code>StageContext</code>/<code>OptimizedBulletPool</code> batch spawn, translate, time-scale, and clear paths. Formal batches create no scene nodes and install no per-bullet Python callbacks.</li><li>Structural/runtime evidence: 45 focused Pattern/authoring/devtools tests passed, and the complete target-environment regression passed (<code>135 passed</code>), including three consecutive full-suite runs after stabilizing the shared Qt application lifetime. Draft 2020-12 schema validation and <code>python -m compileall -q main.py src game_content tools tests</code> also passed.</li><li>Parity evidence: ring, arc, spiral, flower compatibility, player/fixed aim, interval/multi-burst scheduling, identical-seed replay, and two formal preview/game contexts consuming the same runner produced matching traces.</li><li>Performance evidence in <code>touhou_guess</code> (Python 3.12.9, NumPy 2.2.4, Numba 0.63.1): 100 batches × 512 bullets spawned 51,200/51,200 bullets in 0.127511 seconds (401,534 bullets/second), with 100 observed batch calls and zero per-bullet callbacks. This is a recorded representative measurement, not a universal frame-time guarantee.</li><li>Repository evidence: asset validation checked 71 JSON files, 745 sprites, and 142 images with 0 errors and 0 warnings; <code>git diff --check</code> passed.</li><li>Visual evidence: M1 adds no editor surface, so no new visual interaction is claimed. M2 will put controls and diagnostic overlays around this same formal runtime rather than introduce a separate editor-only renderer.</li><li>Acceptance classification: M1 is structurally valid, runtime valid, and performance checked; visual acceptance is not applicable to this milestone.</li><li>Final commands run in the <code>touhou_guess</code> environment: <code>python -m pytest -q</code>, <code>python -m compileall -q main.py src game_content tools tests</code>, <code>python tools/validate_assets.py --format json</code>, and <code>python tools/benchmark_pattern_runtime.py</code>; <code>git diff --check</code> also passed.</li></ul>`,147)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
